function nextPick(){if(G.bpQ>0)openBeaconPick();else if(G.lvlQ>0)openLevelUp();else{scr6(G.world?'world':'play');show('');}}
function openLevelUp(){
  scr6('levelup');pickMode='ship';sfx('level');
  const avail=shuffle(Object.keys(MODS).filter(k=>(G.mods[k]||0)<MODS[k].max&&G.m>=MODS[k].from&&!(G.mode==='endless'&&['tractor','sync','linekit','light'].includes(k))&&!(G.st.weapon==='blast'&&(k==='pierce'||k==='rico'))));
  choices=avail.slice(0,3);if(!choices.length)choices=['__repair'];
  $('#lvEyebrow').textContent=G.briefQ>0?'СТАРТОВЫЙ МОДУЛЬ · '+(G.briefN-G.briefQ+1)+' ИЗ '+G.briefN:'НОВЫЙ МОДУЛЬ'+(G.lvlQ>1?' · ЕЩЁ '+(G.lvlQ-1):'');
  $('#lvAuto').hidden=!(G.briefQ>0);
  $('#cards').classList.remove('bcm');
  $('#cards').innerHTML=choices.map((k,i)=>{
    if(k==='__repair')return `<button class="card" data-i="${i}"><div class="k"><span>${noHeal()?'ЗАРЯД':'РЕМОНТ'}</span><span>${i+1}</span></div><h3>${noHeal()?'Подзарядка':'Полевой ремонт'}</h3><p>Все модули на пределе. ${noHeal()?'Полный накопитель и щит.':'Подлатать корпус.'}</p></button>`;
    const M=MODS[k],l=G.mods[k]||0;
    const pips=Array.from({length:M.max},(_,j)=>`<i class="${j<l?'f':j===l?'n':''}"></i>`).join('');
    return `<button class="card" data-i="${i}"><div class="k"><span>${M.tag}</span><span>${i+1}</span></div><h3>${M.name}</h3><div class="pips">${pips}</div><p>${M.d}</p></button>`;}).join('');
  show('sLevel');const f=$('#cards .card');if(f&&!touchMode)f.focus();
}
function openBeaconPick(){
  scr6('levelup');pickMode='beacon';sfx('level');const bc=G.bc;
  const avail=shuffle(Object.keys(BMODS).filter(k=>(bc.mods[k]||0)<BMODS[k].max));
  choices=avail.slice(0,3);if(!choices.length)choices=['__bcrep'];
  $('#lvEyebrow').textContent='МОДУЛЬ МАЯКА';$('#lvAuto').hidden=true;
  $('#cards').classList.add('bcm');
  $('#cards').innerHTML=choices.map((k,i)=>{
    if(k==='__bcrep')return `<button class="card" data-i="${i}"><div class="k"><span>МАЯК</span><span>${i+1}</span></div><h3>Ремонт маяка</h3><p>Все модули маяка стоят. Починить маяк.</p></button>`;
    const M=BMODS[k],l=bc.mods[k]||0;
    return `<button class="card" data-i="${i}"><div class="k"><span>МАЯК</span><span>${i+1}</span></div><h3>${M.name}</h3>${M.max>1?'<div class="pips">'+Array.from({length:M.max},(_,j)=>`<i class="${j<l?'f':j===l?'n':''}"></i>`).join('')+'</div>':''}<p>${M.d}</p></button>`;}).join('');
  show('sLevel');const f=$('#cards .card');if(f&&!touchMode)f.focus();
}
function choose(i){
  if(G.state!=='levelup'||!choices[i])return;if(pickMode==='zbChoice'){zbChoose(i);return;}const k=choices[i];
  if(pickMode==='beacon'){const bc=G.bc;if(bc){if(k==='__bcrep')bc.hp=Math.min(bc.maxHp,bc.hp+120);else{bc.mods[k]=(bc.mods[k]||0)+1;if(k==='barrier')bc.barrier=100;}}runTake6('bp');}
  else{
    if(k==='__repair'){if(noHeal()){G.player.en=100;G.player.shieldUp=true;G.player.shieldT=0;}else G.player.hp=Math.min(G.st.maxHp,G.player.hp+40);}
    else{const before=G.st.maxHp;G.mods[k]=(G.mods[k]||0)+1;computeStats();if(k==='hull'&&(!noHeal()||G.briefQ>0))G.player.hp+=G.st.maxHp-before;if(k==='shield'&&G.mods.shield===1){G.player.shieldUp=true;}}
    runTake6('lvl');}
  G.player.inv=Math.max(G.player.inv,.6);
  nextPick();
}
$('#cards').addEventListener('click',e=>{const c=e.target.closest('.card');if(c)choose(+c.dataset.i);});
$('#bAuto').onclick=autoPick;

